import{_ as a,o,c as l,a2 as r}from"./chunks/framework.DQhM5RF8.js";const p=JSON.parse('{"title":"Server Rules","description":"","frontmatter":{},"headers":[],"relativePath":"info/rules.md","filePath":"info/rules.md"}'),s={name:"info/rules.md"};function i(t,e,n,h,c,u){return o(),l("div",null,[...e[0]||(e[0]=[r('<h1 id="server-rules" tabindex="-1">Server Rules <a class="header-anchor" href="#server-rules" aria-label="Permalink to &quot;Server Rules&quot;">​</a></h1><p>Follow these simple rules so everyone can have fun playing on LlamaCraft!</p><hr><h2 id="_1-be-nice-respect-others" tabindex="-1">1. Be Nice &amp; Respect Others <a class="header-anchor" href="#_1-be-nice-respect-others" aria-label="Permalink to &quot;1. Be Nice &amp; Respect Others&quot;">​</a></h2><ul><li>Treat other players kindly. No mean words, hate speech, bullying, or swearing in chat.</li><li>Don&#39;t spam messages in chat or keep bugging people who ask to be left alone.</li><li>Listen to server staff. If you have an issue, open a ticket on Discord.</li></ul><hr><h2 id="_2-play-fair-no-cheating" tabindex="-1">2. Play Fair (No Cheating) <a class="header-anchor" href="#_2-play-fair-no-cheating" aria-label="Permalink to &quot;2. Play Fair (No Cheating)&quot;">​</a></h2><ul><li><strong>Allowed Mods</strong>: Performance mods like Sodium, OptiFine, minimaps (without player radars), and Simple Voice Chat.</li><li><strong>Cheating is NOT Allowed</strong>: No hacked clients, no auto-clickers, no X-Ray packs, and no flying hacks.</li><li>If you use hacks, our anti-cheat will ban you automatically.</li></ul><hr><h2 id="_3-respect-bases" tabindex="-1">3. Respect Bases <a class="header-anchor" href="#_3-respect-bases" aria-label="Permalink to &quot;3. Respect Bases&quot;">​</a></h2><ul><li>Don&#39;t try to glitch through walls or steal items from protected bases.</li><li>Don&#39;t build lag machines or drop thousands of items to slow down the server.</li><li>Raid battles only happen during scheduled weekend raid hours.</li></ul><hr><h2 id="_4-voice-chat-rules" tabindex="-1">4. Voice Chat Rules <a class="header-anchor" href="#_4-voice-chat-rules" aria-label="Permalink to &quot;4. Voice Chat Rules&quot;">​</a></h2><ul><li>No screaming loudly into your microphone or playing loud noises.</li><li>Don&#39;t spam meme soundboard clips in crowded areas.</li><li>If someone asks you to mute or quiet down, please be polite and listen.</li></ul>',14)])])}const m=a(s,[["render",i]]);export{p as __pageData,m as default};
